fn ecclesiastes(story: &mut Story) -> Result<(), StoryError> {
    crate::chapter!(story, "Ecclesiastes", 1, "The Teacher opens by calling human effort vaporous, because generations rotate while the earth and its loops remain.", "Rivers run, eyes never finish seeing, and the pursuit of wisdom discovers that more knowledge can also mean more grief.");
    crate::chapter!(story, "Ecclesiastes", 2, "The Teacher tests pleasure, wine, gardens, projects, wealth, music, and every luxury available to a powerful administrator.", "The result is still vapor: wisdom beats folly, but both eventually meet the same shutdown and leave their inventory to another.");
    crate::chapter!(story, "Ecclesiastes", 3, "There is a season for every operation: birth and death, planting and uprooting, weeping and laughing, war and peace.", "Humans sense eternity but cannot inspect the whole timeline, so the Teacher recommends receiving ordinary joy as a gift.");
    crate::chapter!(story, "Ecclesiastes", 4, "The Teacher sees oppression with no comforter, lonely ambition with no heir, and two workers stronger than one isolated worker.", "A poor wise youth can surpass an old foolish king, yet popularity too is vapor because the crowd soon forgets its favorite.");
    crate::chapter!(story, "Ecclesiastes", 5, "Enter the house of the Maintainer with listening enabled, because careless vows and many words create needless debt.", "Wealth brings insomnia and hunger for more, while the best available wisdom is to enjoy one's work as a received portion.");
    crate::chapter!(story, "Ecclesiastes", 6, "A person may possess wealth, honor, and a long life yet fail to enjoy any of them, leaving abundance without a usable interface.", "The Teacher asks who can know what is good for a few vaporous days, since no human can debate the Maintainer into control.");
    crate::chapter!(story, "Ecclesiastes", 7, "A good name, a house of mourning, and patient correction may teach more than a house of feasting and a song of fools.", "Wisdom gives strength, but the Teacher admits that no one is righteous enough to avoid every mistake or fully decode the whole path.");
    crate::chapter!(story, "Ecclesiastes", 8, "Wisdom helps a person navigate a king's command, yet justice still appears delayed and wickedness sometimes receives a long lease.", "The Teacher cannot solve the timing, so he returns to reverence and the modest joy of eating, drinking, and living in the Maintainer's sight.");
    crate::chapter!(story, "Ecclesiastes", 9, "The same fate reaches the righteous and wicked, wise and foolish, because death does not inspect the résumé before closing the process.", "Therefore enjoy bread, love, work, and the day's small gifts; wisdom can save a city even when nobody remembers the poor sage.");
    crate::chapter!(story, "Ecclesiastes", 10, "A little folly spoils wisdom like one dead insect spoiling perfume, and a ruler's mistake can make the whole system wobble.", "The chapter favors skilled hands, warns against lazy roofs and loose tongues, and notes that money answers many things without becoming wisdom.");
    crate::chapter!(story, "Ecclesiastes", 11, "Send bread across the waters, diversify your seed, and act even though clouds do not provide a complete forecast.", "Youth should rejoice in its days while remembering that the Maintainer brings every hidden action into review.");
    crate::chapter!(story, "Ecclesiastes", 12, "Remember the Maintainer before the house grows dark, the grinders cease, and the silver cord snaps at the end of life.", "The Teacher closes the ledger: reverence and faithful practice matter, because every deed eventually enters the final audit.");
    Ok(())
}

